import{_ as o,o as c,c as d,ah as a}from"./chunks/framework.DuX8SFU5.js";const l=JSON.parse('{"title":"Настройка INA228","description":"","frontmatter":{},"headers":[],"relativePath":"am_node_v2/ina228.md","filePath":"am_node_v2/ina228.md"}'),n={name:"am_node_v2/ina228.md"};function _(t,e,r,i,s,u){return c(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="настроика-ina228" tabindex="-1">Настройка INA228 <a class="header-anchor" href="#настроика-ina228" aria-label="Permalink to &quot;Настройка INA228&quot;">​</a></h1><p>Прошивка INA228 поддерживает двенадцать фиксированных адресов INA228, предусмотренных для AM_NODE_V2. Один и тот же модуль используется в прошивках узлов на F1 и H7. Карта адресов и найденная ошибка адресации LOAD3 описаны в <a href="./datasheet#i2c-addresses">даташите AM_NODE_V2</a>.</p><h2 id="настроика" tabindex="-1">Настройка <a class="header-anchor" href="#настроика" aria-label="Permalink to &quot;Настройка&quot;">​</a></h2><p>Параметры <code>ina.c_sens1.role</code>…<code>ina.c_sens4.role</code> задают назначение входов C_SENS1–4 с адресами <code>0x40</code>–<code>0x43</code>: отключён (<code>0</code>), ток (<code>1</code>), давление (<code>2</code>) или длина (<code>3</code>). По умолчанию публикуется ток C_SENS1; остальные каналы C_SENS и публикации каналов нагрузки отключены. В сообщениях тока и длины входам C_SENS1–4 соответствуют идентификаторы цепи или датчика <code>0</code>–<code>3</code>. Для каналов нагрузки следует выбирать идентификаторы цепей, не совпадающие с идентификаторами других источников CircuitStatus на узле.</p><p>Ток рассчитывается по формуле <code>I[A] = Vshunt[uV] / Rshunt[uOhm]</code>. Параметр <code>ina.sensor_shunt_uohm</code> применяется только к каналам C_SENS в режиме измерения тока; значение по умолчанию — <code>20</code>. Для шунтов C_SENS номиналом 2 Ом на AM_NODE_V2 необходимо установить <code>2000000</code>. Для тока нагрузки используются <code>ina.load_shunt_uohm</code> со значением по умолчанию <code>20000</code> (20 мОм) и коэффициент фильтра <code>ina.current.filter_percent</code>, по умолчанию <code>20</code> процентов. Параметры идентификаторов цепей <code>ina.load1.in.circuit_id</code>…<code>ina.load4.out.circuit_id</code> включают публикацию при неотрицательном значении; <code>-1</code> отключает канал.</p><p>Калибровка давления и длины задаётся граничными значениями тока из спецификации датчика, в целых миллиамперах. Для каждого канала параметры <code>.current.in_min_ma</code> и <code>.current.in_max_ma</code> по умолчанию равны <code>4</code> и <code>20</code>. Текущий интерфейс целочисленных параметров не поддерживает дробные значения миллиампер; сами измерения при этом не округляются до целых миллиампер. Прошивка пересчитывает границы с учётом фиксированных шунтов C_SENS номиналом 2 Ом (<code>1 мА = 2000 мкВ</code>), независимо от <code>ina.sensor_shunt_uohm</code>. Поэтому режимы давления и длины требуют входов с шунтами 2 Ом. Границы давления задаются параметрами <code>.pressure.out_min_pa</code> и <code>.pressure.out_max_pa</code>, а длины — <code>.length.out_min_mm</code> и <code>.length.out_max_mm</code>; длина публикуется в метрах. Входное значение ограничивается интервалом калибровки; обратный порядок границ позволяет инвертировать зависимость. Если границы калибровки совпадают, при токе не выше этой границы выбирается значение <code>.pressure.out_min_pa</code> или <code>.length.out_min_mm</code>, а при превышении — <code>.pressure.out_max_pa</code> или <code>.length.out_max_mm</code>. Для датчика длины 4–20 мА с диапазоном 0–1000 мм на C_SENS2 необходимо задать <code>ina.c_sens2.role = 3</code>, <code>ina.c_sens2.current.in_min_ma = 4</code>, <code>ina.c_sens2.current.in_max_ma = 20</code>, <code>ina.c_sens2.length.out_min_mm = 0</code> и <code>ina.c_sens2.length.out_max_mm = 1000</code>. Для датчика давления следует выбрать режим <code>2</code> и задать физические границы в паскалях согласно спецификации датчика.</p><p>Несколько каналов длины публикуются независимо друг от друга. Поскольку сообщение StaticPressure не содержит идентификатора датчика, давление публикует только исправный канал с наименьшим номером. При его отказе публикация переключается на следующий исправный канал; после восстановления приоритет возвращается каналу с меньшим номером. При настройке нескольких каналов давления необходимо учитывать этот порядок выбора источника.</p><h2 id="периодичность-опроса-и-обработка-отказов" tabindex="-1">Периодичность опроса и обработка отказов <a class="header-anchor" href="#периодичность-опроса-и-обработка-отказов" aria-label="Permalink to &quot;Периодичность опроса и обработка отказов&quot;">​</a></h2><p>Модуль обслуживает не более одного устройства за вызов с периодом 5 мс; целевая частота опроса каждого включённого канала — 10 Гц. Проверка идентификаторов устройства и чтение измерений выполняются в разных вызовах. После успешной инициализации шина повторно не инициализируется; при ошибке инициализации или недоступности устройства попытки повторяются раз в секунду. Чтение I²C остаётся синхронным, поэтому задержка при отказе ограничивается существующими тайм-аутами HAL; жёсткое время выполнения не гарантируется. Отключённые устройства не опрашиваются. При отказе публикация измерений этого устройства прекращается, остальные каналы продолжают работать; ошибки одного адреса выводятся не чаще раза в секунду. Состояние модуля — OK, если работают все включённые устройства, предупреждение при частичном отказе и ошибка при отказе всех включённых устройств.</p><h2 id="обновление-прошивки" tabindex="-1">Обновление прошивки <a class="header-anchor" href="#обновление-прошивки" aria-label="Permalink to &quot;Обновление прошивки&quot;">​</a></h2><p>Состав и порядок параметров изменились, а сохранённые значения хранятся по индексам. Параметры шунтов: <code>ina.load_shunt_uohm</code> для нагрузок и <code>ina.sensor_shunt_uohm</code> для каналов C_SENS в режиме тока; оба значения задаются в микроомах. Параметры <code>.cal_min_uv</code>/<code>.cal_max_uv</code> заменены на <code>.current.in_min_ma</code>/<code>.current.in_max_ma</code>; сохранённые значения в микровольтах нельзя использовать как миллиамперы, автоматического пересчёта нет. Для переноса прежней калибровки входов с шунтами 2 Ом следует разделить границы в микровольтах на 2000; дробный результат нельзя точно представить целочисленным параметром в миллиамперах. После установки этой версии необходимо выполнить <strong>Erase All</strong> в dronecan_gui_tool и до начала работы заново задать идентификатор узла, калибровку, идентификаторы цепей нагрузки, настройки BYPASS и MAX14906. Нельзя восстанавливать старый файл параметров без переноса настроек INA в новую структуру отдельных каналов. Модули <code>ina234_length</code> и <code>ina234_pressure</code> считаются устаревшими: они предназначены для платы, которая больше не выпускается, и используются только на нескольких оставшихся оценочных платах. Это ограничение относится к модулям, а не к драйверу INA234. Модуль <code>ina228_loads</code> сохранён для совместимости; актуальные прошивки узлов используют <code>ina228_sensor</code>. Модули ina228_loads и ina228_sensor нельзя включать в одну сборку одновременно.</p><h2 id="прошивки" tabindex="-1">Прошивки <a class="header-anchor" href="#прошивки" aria-label="Permalink to &quot;Прошивки&quot;">​</a></h2><ul><li><a href="./firmware_am_node_default">am_node_default</a></li></ul>',13)])])}const h=o(n,[["render",_]]);export{l as __pageData,h as default};
